import java.io.*;import javax.microedition.lcdui.*;
final class Ranking793{
 final PhoneCanvas c;boolean opened;int count,selected;long poll;final int[] id=new int[128],xp=new int[128],weapon=new int[128],damage=new int[128],wins=new int[128];final String[] names=new String[128];Image frame;final Image[] levels=new Image[128],weapons=new Image[10];
 Ranking793(PhoneCanvas c){this.c=c;}
 void releaseArt(){frame=null;for(int i=0;i<128;i++)levels[i]=null;for(int i=0;i<10;i++)weapons[i]=null;}
 void open(){if(!c.onlineAccount()){c.net.loginForm(false);return;}opened=true;selected=0;c.net.request("ranking");}
 void read(DataInputStream in)throws IOException{int n=in.readUnsignedShort();if(n>128)throw new IOException("Sai danh sách xếp hạng");for(int i=0;i<n;i++){id[i]=in.readInt();xp[i]=in.readInt();names[i]=in.readUTF();weapon[i]=in.readUnsignedByte();damage[i]=in.readInt();wins[i]=in.readInt();}for(int i=0;i<n;i++)levels[i]=null;count=n;selected=Math.min(selected,Math.max(0,n-1));poll=System.currentTimeMillis();}
 void draw(){if(frame==null)frame=NativeUi.fit(c.combatRoomArt("settings743-popup"),308*c.s,228*c.s,5*c.s);c.all();c.img(frame,6,6);c.pcCenter("XẾP HẠNG ONLINE",160,15);c.rect(14,35,292,173,0xfff9e8);c.rect(14,35,292,16,0x987342);c.pcText("#   Cấp       Nhân vật          Dame   Thắng",19,39);int first=selected/6*6;for(int row=0;row<6&&first+row<count;row++){int i=first+row,y=54+row*25;c.rect(16,y,288,24,0xfff9e8);c.pcText(""+(i+1),20,y+4);if(levels[i]==null)levels[i]=NativeUi.fit(c.levelIcon(xp[i]),22*c.s,22*c.s,0);c.img(levels[i],36,y+1);int w=weapon[i];if(w>=0&&w<10&&c.weapons[w]!=null){if(weapons[w]==null)weapons[w]=NativeUi.fit(c.weapons[w],22*c.s,22*c.s,0);c.img(weapons[w],60,y+1);}c.pcText(c.pcShort(names[i],88),86,y+7);c.pcText(""+damage[i],182,y+5);c.pcText(""+wins[i],258,y+5);if(i==selected){c.line(16,y,304,y,0xe5ad34);c.line(16,y+24,304,y+24,0xe5ad34);c.line(16,y,16,y+24,0xe5ad34);c.line(304,y,304,y+24,0xe5ad34);}}c.pcCenter(count==0?"Chưa có tài khoản đủ điều kiện":"Lên/xuống • OK: xem • Mềm phải: đóng",160,215);}
 void key(int key,int dir,boolean ok){if(key==-7){opened=false;return;}if(dir!=0)selected=Battle.clamp(selected+(dir==4||dir==1?-1:1),0,Math.max(0,count-1));else if(ok&&count>0){opened=false;c.net.social.opened=c.net.social.viewing=c.net.social.profileLoading=true;c.net.social.target=id[selected];c.net.request("playerinfo");}}
 void pointer(int x,int y){if(y<35||y>208){opened=false;return;}int row=(y-54)/25,i=selected/6*6+row;if(row>=0&&row<6&&i<count){if(i==selected)key(0,0,true);else selected=i;}}
}
